<script>
import AiViewTerm from '../ui/AiViewTerm.vue';

export default {
  name: 'SiteAiPathExplorer',
  components: { AiViewTerm },
  emits: ['open-search', 'open-ask', 'compose-view'],
  data() {
    return {
      active: 'search',
      paths: [
        {
          id: 'search',
          verb: 'Find',
          label: 'Search',
          kicker: 'Across the whole site',
          title: 'Search once and land on the right passage',
          summary: 'Search moves across every page, shows the relevant passage, highlights the match, and opens the original material at its precise location. Lexical and semantic ranking run together in the browser.',
          action: 'Try Search',
          event: 'open-search',
          steps: [
            { title: 'Embed', body: 'Represent every passage and the query in the same semantic space.' },
            { title: 'Retrieve', body: 'Compare exact wording and meaning across the complete index.' },
            { title: 'Fuse', body: 'Merge both rankings while protecting strong name and phrase matches.' },
            { title: 'Open', body: 'Send the reader back to the original material and its precise location.' },
          ],
        },
        {
          id: 'ask',
          verb: 'Answer',
          label: 'Ask',
          kicker: 'A grounded conversation',
          title: 'Ask a question and keep following it',
          summary: 'Ask turns supporting passages into a concise response with citations, then suggests follow-up questions grounded in the site. An edge model writes within the retrieved evidence.',
          action: 'Ask the site',
          event: 'open-ask',
          steps: [
            { title: 'Retrieve', body: 'Collect the site material most relevant to the visitor’s question.' },
            { title: 'Ground', body: 'Number the selected passages and define the evidence boundary.' },
            { title: 'Generate', body: 'Write the answer with a language model running through an edge worker.' },
            { title: 'Cite', body: 'Connect the response back to the original pages it used.' },
          ],
        },
        {
          id: 'view',
          verb: 'Compose',
          label: 'View',
          kicker: 'A new reading path',
          title: 'Turn an angle into a source-linked page',
          summary: 'The composer gathers material from across the site, connects it around one angle, and places original components beside the narrative. The finished page becomes a permanent, dated snapshot.',
          action: 'Compose',
          event: 'compose-view',
          steps: [
            { title: 'Gather', body: 'Retrieve a broader set of material that can support the chosen angle.' },
            { title: 'Plan', body: 'Select the useful sources and arrange them into a reading sequence.' },
            { title: 'Compose', body: 'Write the narrative and place original site components where they add evidence.' },
            { title: 'Preserve', body: 'Save the result and its sources as a permanent, shareable snapshot.' },
          ],
        },
      ],
    };
  },
  computed: {
    current() {
      return this.paths.find((path) => path.id === this.active) || this.paths[0];
    },
  },
  methods: {
    runCurrent() {
      this.$emit(this.current.event);
    },
  },
};
</script>

