<template>
  <transition name="view-composer-fade">
    <div v-if="open" class="view-composer-overlay" @click.self="closeComposer">
      <section class="view-composer" role="dialog" aria-modal="true" aria-labelledby="view-composer-title">
        <header>
          <div>
            <p>Compose a <AiViewTerm /></p>
            <h2 id="view-composer-title">What would you like to see?</h2>
          </div>
          <button type="button" class="view-composer-close" aria-label="Close View composer" :disabled="busy" @click="closeComposer">
            <span>Close</span><span aria-hidden="true">&times;</span>
          </button>
        </header>

        <p class="view-composer-intro">Describe a question, theme, or perspective. AI will follow the relevant connections across Henry&rsquo;s site and compose them into a focused <AiViewTerm />.</p>

        <form @submit.prevent="compose">
          <textarea
            id="view-composer-prompt"
            ref="prompt"
            v-model="prompt"
            aria-label="Describe the View you want"
            rows="3"
            maxlength="800"
            placeholder="I want to understand Henry through..."
            :disabled="busy"
            @keydown.meta.enter.prevent="compose"
            @keydown.ctrl.enter.prevent="compose"
          ></textarea>

          <div v-if="!busy && !message" class="view-composer-examples" aria-label="Example perspectives">
            <button v-for="example in examples" :key="example" type="button" @click="useExample(example)">{{ example }}</button>
          </div>

          <div v-if="busy" class="view-composer-progress" role="status" aria-live="polite">
            <MorphingInfinity aria-hidden="true" />
            <div><strong>Composing your <AiViewTerm /></strong><span class="view-composer-progress-copy">Following connections across Henry&rsquo;s site</span></div>
          </div>

          <div v-else-if="message" class="view-composer-message" role="status">
            <strong>Give this View a little more direction</strong>
            <p>{{ message }}</p>
          </div>

          <footer>
            <span>⌘ Enter</span>
            <button type="submit" :disabled="busy || !prompt.trim()">
              <span>Compose <AiViewTerm /></span><span aria-hidden="true">↗</span>
            </button>
          </footer>
        </form>
      </section>
    </div>
  </transition>
</template>

<script>
import MorphingInfinity from './ui/MorphingInfinity.vue';
import AiViewTerm from './ui/AiViewTerm.vue';
import { candidatesForView } from '../utils/viewRetrieval';
import { requestView } from '../utils/viewSite';
import { sanitizeViewResponse, validateViewResponse } from '../utils/viewValidation';
import {
  addAskTurn,
  createAskSession,
  setAskOrigin,
  setAskView,
} from '../utils/askSession';

function sourceIds(view) {
  const ids = [];
  for (const section of view?.sections || []) {
    for (const block of section.blocks || []) {
      if (block?.source_id) ids.push(block.source_id);
      if (Array.isArray(block?.source_ids)) ids.push(...block.source_ids);
    }
  }
  return [...new Set(ids)];
}

export default {
  name: 'ViewComposer',
  components: { AiViewTerm, MorphingInfinity },
  data() {
    return {
      open: false,
      prompt: '',
      busy: false,
      message: '',
      controller: null,
      examples: [
        'Henry through the places that shaped him',
        'How Henry connects research and practical systems',
        'Ideas that recur across Henry’s work',
      ],
    };
  },
  mounted() {
    this._onKeydown = (event) => {
      if (event.key === 'Escape' && this.open && !this.busy) this.closeComposer();
    };
    window.addEventListener('keydown', this._onKeydown);
  },
  beforeUnmount() {
    window.removeEventListener('keydown', this._onKeydown);
    this.controller?.abort();
    document.body.style.overflow = '';
  },
  methods: {
    openComposer() {
      this.open = true;
      this.message = '';
      document.body.style.overflow = 'hidden';
      this.$nextTick(() => this.$refs.prompt?.focus());
    },
    closeComposer() {
      if (this.busy) return;
      this.open = false;
      this.message = '';
      document.body.style.overflow = '';
    },
    useExample(example) {
      this.prompt = example;
      this.message = '';
      this.$nextTick(() => this.$refs.prompt?.focus());
    },
    async compose() {
      const intent = this.prompt.trim();
      if (!intent || this.busy) return;
      this.controller?.abort();
      this.controller = new AbortController();
      this.busy = true;
      this.message = '';
      try {
        const sources = await candidatesForView({ message: intent, session: null, latestMessage: intent });
        const response = await requestView({
          message: intent,
          conversation: [],
          sources,
          meta: { surface: 'views', turn_index: 1 },
          signal: this.controller.signal,
        });
        const sanitized = sanitizeViewResponse(response, sources);
        const validation = validateViewResponse(sanitized, sources);
        if (!validation.ok) throw new Error(validation.error || 'The View could not be composed.');
        if (sanitized.action === 'answer') {
          this.message = validation.answer?.message || 'Try describing what you want to understand about Henry, or choose one of the examples below.';
          return;
        }
        const view = validation.view || sanitized.view;
        let session = createAskSession({ route: '/views' });
        session = addAskTurn(session, { role: 'user', text: intent, source_ids: [] });
        session = addAskTurn(session, { role: 'assistant', text: 'View composed.', source_ids: sourceIds(view) });
        session = setAskView(session, view);
        setAskOrigin(session, '/views');
        document.body.style.overflow = '';
        this.open = false;
        await this.$router.push('/view');
      } catch (error) {
        if (error?.name !== 'AbortError') {
          this.message = String(error?.message || 'Composition is temporarily unavailable. Please try again.').slice(0, 300);
        }
      } finally {
        this.busy = false;
        this.controller = null;
      }
    },
  },
};
</script>

