          class="stage-wrap"
          :class="{ open: openStage === index }"
        >
          <button
            class="stage"
            type="button"
            :aria-expanded="(openStage === index).toString()"
            @click="openStage = openStage === index ? null : index"
          >
            <span class="stage-index">{{ index + 1 }}</span>
